import {makeRack} from './war-rack-core.js';
export const BUS_RACKS=[['Vocal Bus',-17,2,24,170,.8],['Drum Bus',-18,2.5,30,130,.75],['Instrument Bus',-18,1.5,35,220,.65],['Parallel Compression',-26,5,12,120,1],['Mix Bus',-14,1.5,40,230,.7]].map(([name,threshold,ratio,attack,release,mix],i)=>makeRack('bus-'+i,'BUS / '+name,'Tous','Bus','mix',[['vectoreq',{g1:-.4,g4:.4}],['circuitbus',{threshold,ratio,attack,release,mix}]],'Apply only to an existing bus. Routing and send levels remain unchanged. Parallel compression requires a separate routed aux.'));
BUS_RACKS.push(makeRack('bus-reverb','BUS / Reverb Aux','Tous','Bus','mix',[['exospace',{mix:1}]],'Wet auxiliary; route sends manually.'),makeRack('bus-delay','BUS / Delay Aux','Tous','Bus','mix',[['alterecho',{mix:1,feedback:.2}]],'Wet auxiliary; route sends manually.'));
export function trimStage(gainDb){if(!Number.isFinite(gainDb)||gainDb< -12||gainDb>12)throw Error('Trim hors plage ±12 dB');return {id:'tilteq',values:{tilt:0,pivot:1000,mix:1,output:gainDb}};}
